<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Teacher'],true)){http_response_code(403);exit('Access denied.');}
$term=filter_var($_GET['term_id']??null,FILTER_VALIDATE_INT);$class=filter_var($_GET['class_id']??null,FILTER_VALIDATE_INT);if(!$term||!$class){http_response_code(400);exit('A term and class are required.');}
$pdo=db();$q=$pdo->prepare('SELECT c.form_level,c.stream,c.academic_year,c.class_teacher_id,t.academic_year AS term_year,t.name AS term_name,t.starts_on,t.ends_on FROM class_groups c JOIN school_terms t ON t.id=:term WHERE c.id=:class');$q->execute(['term'=>$term,'class'=>$class]);$context=$q->fetch();if(!$context||(int)$context['academic_year']!==(int)$context['term_year']){http_response_code(404);exit('Class and term were not found.');}if($user['role']==='Teacher'){$allowed=$pdo->prepare('SELECT COUNT(*) FROM class_groups c WHERE c.id=:class AND (c.class_teacher_id=:teacher_class OR EXISTS (SELECT 1 FROM class_subjects cs WHERE cs.class_id=c.id AND cs.teacher_id=:teacher_subject))');$allowed->execute(['class'=>$class,'teacher_class'=>$user['id'],'teacher_subject'=>$user['id']]);if(!(int)$allowed->fetchColumn()){http_response_code(403);exit('You are not assigned to this class.');}}
$stmt=$pdo->prepare("SELECT s.admission_no,s.first_name,s.last_name,SUM(a.status='Present') AS present_count,SUM(a.status='Late') AS late_count,SUM(a.status='Absent') AS absent_count,SUM(a.status='Excused') AS excused_count FROM (SELECT DISTINCT st.id,st.admission_no,st.first_name,st.last_name FROM students st JOIN student_enrolments e ON e.student_id=st.id WHERE e.academic_year=:year AND e.form_level=:form AND COALESCE(e.stream,'')=:stream AND e.start_date<=:term_end AND (e.end_date IS NULL OR e.end_date>=:term_start)) s LEFT JOIN attendance a ON a.student_id=s.id AND a.attendance_date BETWEEN :start_date AND :end_date GROUP BY s.admission_no,s.first_name,s.last_name ORDER BY s.last_name,s.first_name");$stmt->execute(['year'=>$context['term_year'],'form'=>$context['form_level'],'stream'=>$context['stream'],'term_end'=>$context['ends_on'],'term_start'=>$context['starts_on'],'start_date'=>$context['starts_on'],'end_date'=>$context['ends_on']]);
$filename='attendance-form-'.(int)$context['form_level'].'-'.preg_replace('/[^A-Za-z0-9_-]/','',(string)$context['stream']).'-'.$term.'.csv';header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$filename.'"');header('X-Content-Type-Options: nosniff');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Term',$context['term_name'],'Academic year',$context['term_year']]);fputcsv($out,['Admission number','Learner','Present','Late','Absent','Excused','Recorded days','Attendance rate']);while($row=$stmt->fetch()){$present=(int)$row['present_count'];$late=(int)$row['late_count'];$absent=(int)$row['absent_count'];$excused=(int)$row['excused_count'];$denominator=$present+$late+$absent;$rate=$denominator?number_format(($present+$late)/$denominator*100,1).'%':'';$values=[$row['admission_no'],$row['first_name'].' '.$row['last_name'],$present,$late,$absent,$excused,$present+$late+$absent+$excused,$rate];foreach($values as &$value)if(is_string($value)&&preg_match('/^[=+\-@\t\r]/',$value))$value="'".$value;unset($value);fputcsv($out,$values);}fclose($out);exit;
